import './style.css'
import ReactDOM from 'react-dom/client'
import { useState } from 'react'

import LeftBar from './LeftBar'
import Room from './Room'
import { normalizeRoomShape } from './roomShape'

const root = ReactDOM.createRoot(document.querySelector('#root'))


export default function App() {

    const [roomWidth, setRoomWidth] = useState(() => {
        const v = parseInt(localStorage.getItem('roomWidth'), 10)
        return Number.isFinite(v) ? v : 10
    })
    const [roomHeight, setRoomHeight] = useState(() => {
        const v = parseInt(localStorage.getItem('roomHeight'), 10)
        return Number.isFinite(v) ? v : 10
    })

    const [isMakingRoom, setIsMakingRoom] = useState(() => {
        const w = localStorage.getItem('roomWidth');
        const h = localStorage.getItem('roomHeight');
        return (w && h);
    });

    const [roomVisible, setRoomVisible] = useState(() => {
        const w = localStorage.getItem('roomWidth')
        const h = localStorage.getItem('roomHeight')
        return Boolean(w && h)
    })

    const [makeMode, setMakeMode] = useState(false);

    const [roomShape, setRoomShape] = useState(() => {
        const saved = localStorage.getItem('roomShape')
        return normalizeRoomShape(saved)
    })

    const handleCreate = (width, height) => {
        // 既に間取り確定済みなら何もしない
        if (isMakingRoom) return;
        setRoomWidth(width)
        setRoomHeight(height)
        setRoomVisible(true)
        try {
            localStorage.setItem('roomWidth', String(width))
            localStorage.setItem('roomHeight', String(height))
        } catch (e) {
        }
        setIsMakingRoom(true)
    }

    // handleStartはリセット時のみ有効
    const handleStart = (making) => {
        if (!making) setIsMakingRoom(false)
    }

    // 間取り確定後は作成モードに遷移不可
    const handleMode = (mode) => {
        if (isMakingRoom) return;
        setMakeMode(!mode);
    }

    const handleDelete = () => {
        try {
            localStorage.removeItem('roomWidth')
            localStorage.removeItem('roomHeight')
            localStorage.removeItem('roomShape')
        } catch (e) {}
        setRoomVisible(false)
        setRoomWidth(10)
        setRoomHeight(10)
        setIsMakingRoom(false)
        setRoomShape('rectangle')
        setMakeMode(false)
    }

    const handleUpdateRoomShape = (shapeId) => {
        const next = normalizeRoomShape(shapeId)
        setRoomShape(next)
        try {
            localStorage.setItem('roomShape', next)
        } catch (e) {}
    }

    const handleUpdateRoomSize = (nextWidth, nextHeight) => {
        const safeWidth = Math.max(1, parseInt(nextWidth, 10) || 1)
        const safeHeight = Math.max(1, parseInt(nextHeight, 10) || 1)
        setRoomWidth(safeWidth)
        setRoomHeight(safeHeight)
        try {
            localStorage.setItem('roomWidth', String(safeWidth))
            localStorage.setItem('roomHeight', String(safeHeight))
        } catch (e) {}
    }




    const [furnitureList, setFurnitureList] = useState(() => {
        try {
            const raw = localStorage.getItem('furnitureList')
            if (!raw) return []
            const parsed = JSON.parse(raw)
            return Array.isArray(parsed) ? parsed : []
        } catch (e) {
            return []
        }
    })

    const persistFurniture = (list) => {
        try { localStorage.setItem('furnitureList', JSON.stringify(list)) } catch (e) {}
    }

    const handleAddFurniture = (f) => {
        if (!f) return
        setFurnitureList(prev => {
            const next = [...prev, f]
            persistFurniture(next)
            return next
        })
    }

    const handleRemoveFurniture = (index) => {
        setFurnitureList(prev => {
            const next = prev.filter((_, i) => i !== index)
            persistFurniture(next)
            return next
        })
    }

    const [selectedIndex, setSelectedIndex] = useState(null)

    const handleClearFurniture = () => {
        setFurnitureList([])
        persistFurniture([])
        setSelectedIndex(null)
    }
    

    const handleSelectFurniture = (index) => {
        setSelectedIndex(prev => (prev === index ? null : index))
    }

    const handleUpdateFurniture = (index, updated) => {
        setFurnitureList(prev => {
            const next = prev.map((it, i) => i === index ? { ...it, ...updated } : it)
            persistFurniture(next)
            return next
        })
    }

    const [switchDim, setSwitchDim] = useState(false)

    const [wallColor, setWallColor] = useState(() => {
        const v = localStorage.getItem('wallColor')
        return v || '#e8e0d5'
    })

    const handleUpdateWallColor = (color) => {
        setWallColor(color)
        try {
            localStorage.setItem('wallColor', color)
        } catch (e) {}
    }

    const [floorColor, setFloorColor] = useState(() => {
        const v = localStorage.getItem('floorColor')
        return v || '#8b5a2b'
    })

    const handleUpdateFloorColor = (color) => {
        setFloorColor(color)
        try {
            localStorage.setItem('floorColor', color)
        } catch (e) {}
    }

    

    return (
        <div className="appContainer">
            <LeftBar
                onCreate={handleCreate}
                onStart={handleStart}
                onMode={handleMode}
                onDelete={handleDelete}
                onAddFurniture={handleAddFurniture}
                onRemoveFurniture={handleRemoveFurniture}
                onClearFurniture={handleClearFurniture}
                onUpdateFurniture={handleUpdateFurniture}
                selectedIndex={selectedIndex}
                onSelectFurniture={handleSelectFurniture}
                furnitureList={furnitureList}
                making={isMakingRoom}
                isMakingMode={makeMode}
                initialWidth={roomWidth}
                initialHeight={roomHeight}
                switchDim={switchDim}
                onSwitchDim={setSwitchDim}
                onUpdateWallColor={handleUpdateWallColor}
                initialWallColor={wallColor}
                onUpdateFloorColor={handleUpdateFloorColor}
                initialFloorColor={floorColor}
            />
            {roomVisible || makeMode ? (
                <Room 
                    width={roomWidth} 
                    height={roomHeight} 
                    roomShape={roomShape}
                    onUpdateRoomShape={handleUpdateRoomShape}
                    onUpdateRoomSize={handleUpdateRoomSize}
                    furnitureList={furnitureList} 
                    selectedIndex={selectedIndex} 
                    onSelectFurniture={handleSelectFurniture} 
                    onUpdateFurniture={handleUpdateFurniture}
                    switchDim={switchDim} 
                    wallColor={wallColor} 
                    floorColor={floorColor} 
                    isMakingMode={makeMode} 
                />
            ) : (
                <div className="room" />
            )}
        </div>
    )
}

root.render(<App />)